struct vector3d
{
  float x;
  float y;
  float z;
};

class region_node;

class region
{
public:
  static unsigned int visit_key;
  static void prepare_for_visiting() { ++visit_key; }
};
__asm__(".equ _6region$visit_key, 0x00434948");

class entity
{
public:
  static unsigned int visit_key;
  static void prepare_for_visiting() { visit_key++; }
};
__asm__(".equ _6entity$visit_key, 0x003E5AE8");

class terrain
{
public:
  bool find_intersection(const vector3d&, const vector3d&, vector3d&, vector3d&);
};
__asm__(".equ find_intersection__7terrainRC8vector3dT1R8vector3dT3, 0x002E8DD8");

struct world_layout
{
  char padding[0xec];
  terrain* terrain_ptr;
};
extern world_layout* world_ptr;
__asm__(".equ world_ptr, 0x00431A8C");

static bool find_intersection_with_entities(
  const vector3d&, const vector3d&, region_node*, unsigned int,
  vector3d*, vector3d*, region_node**, entity**)
  __asm__("find_intersection_with_entities__FRC8vector3dT0PQ2t5graph4Z7stringxZP6regionZP6portalZt4less1Z7stringx4nodeUiP8vector3dT4PPQ2t5graph4Z7stringxZP6regionZP6portalZt4less1Z7stringx4nodePP6entity");

bool find_intersection(
  const vector3d& p0, const vector3d& p1,
  region_node* start_region,
  unsigned int flags,
  vector3d* hit_loc, vector3d* hit_normal,
  region_node** hit_region, entity** hit_entity)
  __asm__("find_intersection__FRC8vector3dT0PQ2t5graph4Z7stringxZP6regionZP6portalZt4less1Z7stringx4nodeUiP8vector3dT4PPQ2t5graph4Z7stringxZP6regionZP6portalZt4less1Z7stringx4nodePP6entity");

bool find_intersection(
  const vector3d& p0, const vector3d& p1,
  region_node* start_region,
  unsigned int flags,
  vector3d* hit_loc, vector3d* hit_normal,
  region_node** hit_region, entity** hit_entity)
{
  bool hit = false;
  if ( flags & 0x0001 )
  {
    hit = world_ptr->terrain_ptr->find_intersection( p0, p1, *hit_loc, *hit_normal );
  }

  if ( start_region && (flags&0x003e) )
  {
    vector3d tp1;
    if ( hit )
      tp1 = *hit_loc;
    else
      tp1 = p1;
    region::prepare_for_visiting();
    entity::prepare_for_visiting();
    hit |= find_intersection_with_entities( p0, tp1,
                                            start_region,
                                            flags,
                                            hit_loc, hit_normal,
                                            hit_region, hit_entity );
  }

  return hit;
}
